export function LogoScene({ sceneKey }: { sceneKey: string }) {
  const isConstructing = ['construct', 'weave', 'solidify', 'ambient'].includes(sceneKey);
  const isSolidifying = ['solidify', 'ambient'].includes(sceneKey);
  const isAmbient = sceneKey === 'ambient';

  const clipStart = 'inset(100% -20% -20% -20%)';
  const clipEnd = 'inset(-20% -20% -20% -20%)';

  const particles = useMemo(() => Array.from({ length: 8 }).map((_, i) => ({
    id: i,
    left: 15 + Math.random() * 70, // Keep in bounds horizontally
    delay: Math.random() * 2,
    size: 2 + Math.random() * 3,
    duration: 3 + Math.random() * 3,
  })), []);

  return (
    <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
      
      {/* Floating Ambient Particles Layer */}
      {isSolidifying && (
        <div className="absolute inset-0 overflow-hidden pointer-events-none z-0">
          {particles.map(p => (
            <motion.div
              key={p.id}
              className="absolute rounded-full"
              style={{
                left: `${p.left}%`,
                width: p.size,
                height: p.size,
                backgroundColor: '#31CD65',
                boxShadow: '0 0 8px #31CD65',
              }}
              initial={{ top: '80%', opacity: 0 }}
              animate={{ 
                top: '10%', 
                opacity: [0, 0.5, 0] 
              }}
              transition={{
                duration: p.duration,
                delay: p.delay,
                repeat: Infinity,
                ease: "linear"
              }}
            />
          ))}
        </div>
      )}

      {/* Main Logo Container */}
      <motion.div
        className="relative w-[55%] max-w-[400px] aspect-[1065/1417] z-10"
      >
        {/* Stroke Construction Layer - Masked via clipPath for bottom-to-top reveal */}
        <motion.div
          className="absolute inset-0"
          initial={{ clipPath: clipStart }}
          animate={{ clipPath: isConstructing ? clipEnd : clipStart }}
          transition={{ duration: sceneKey === 'black' ? 0.1 : 2.8, ease: "linear" }}
        >
          {/* Under Beam Stroke (Softer, Thicker, Delayed less) */}
          <motion.svg
            viewBox="0 0 1065 1417"
            className="absolute inset-0 w-full h-full"
            style={{ filter: "drop-shadow(0 0 4px #31CD65)" }}
          >
            <motion.path
              d={PATH_DATA}
              fill="none"
              stroke="#31CD65"
              strokeWidth="16"
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ 
                pathLength: isConstructing ? 1 : 0,
                opacity: sceneKey === 'black' ? 0 : isSolidifying ? 0 : 0.3 
              }}
              transition={{ 
                pathLength: { duration: sceneKey === 'black' ? 0.1 : 2.8, ease: "easeInOut" },
                opacity: { duration: 0.3 }
              }}
            />
          </motion.svg>

          {/* Over Beam Stroke (Sharper, Brighter, Delayed slightly to simulate weaving) */}
          <motion.svg
            viewBox="0 0 1065 1417"
            className="absolute inset-0 w-full h-full"
            animate={{
              filter: sceneKey === 'weave'
                ? ['drop-shadow(0 0 8px #31CD65)', 'drop-shadow(0 0 32px #31CD65)', 'drop-shadow(0 0 12px #31CD65)']
                : 'drop-shadow(0 0 12px #31CD65)'
            }}
            transition={{ duration: sceneKey === 'weave' ? 0.6 : 0.2, ease: "easeInOut" }}
          >
            <motion.path
              d={PATH_DATA}
              fill="none"
              stroke="#31CD65"
              strokeWidth="8"
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ 
                pathLength: isConstructing ? 1 : 0,
                opacity: sceneKey === 'black' ? 0 : isSolidifying ? 0 : 1 
              }}
              transition={{ 
                pathLength: { duration: sceneKey === 'black' ? 0.1 : 2.8, ease: "easeInOut", delay: sceneKey === 'black' ? 0 : 0.15 },
                opacity: { duration: 0.3 }
              }}
            />
          </motion.svg>
        </motion.div>

        {/* Solid Fill Layer - Transitions in during 'solidify' phase */}
        <motion.div
          className="absolute inset-0"
          initial={{ opacity: 0 }}
          animate={{ opacity: isSolidifying ? 1 : 0 }}
          transition={{ duration: sceneKey === 'black' ? 0.1 : 0.6, ease: "easeInOut" }}
        >
          <motion.svg
            viewBox="0 0 1065 1417"
            className="absolute inset-0 w-full h-full"
            animate={{
              filter: isAmbient
                ? ['drop-shadow(0 0 6px #31CD65)', 'drop-shadow(0 0 14px #31CD65)', 'drop-shadow(0 0 6px #31CD65)']
                : 'drop-shadow(0 0 8px #31CD65)'
            }}
            transition={{ 
              duration: isAmbient ? 3 : 0.6, 
              repeat: isAmbient ? Infinity : 0, 
              ease: "easeInOut" 
            }}
          >
            <path d={PATH_DATA} fill="#31CD65" />
          </motion.svg>
        </motion.div>

        {/* Light Sweep Highlight Layer - Sweeps across the logo shape during 'solidify' */}
        <motion.div
          className="absolute inset-0 mix-blend-screen"
          initial={{ opacity: 0 }}
          animate={{ opacity: sceneKey === 'solidify' ? 1 : 0 }}
          transition={{ duration: 0.3 }}
        >
          <svg viewBox="0 0 1065 1417" className="w-full h-full absolute inset-0">
            <defs>
              <clipPath id="logo-clip">
                <path d={PATH_DATA} />
              </clipPath>
              <linearGradient id="sweep-gradient" x1="0" y1="0" x2="1" y2="0" gradientTransform="rotate(35)">
                <stop offset="0%" stopColor="white" stopOpacity="0" />
                <stop offset="40%" stopColor="white" stopOpacity="0" />
                <stop offset="50%" stopColor="white" stopOpacity="0.8" />
                <stop offset="60%" stopColor="white" stopOpacity="0" />
                <stop offset="100%" stopColor="white" stopOpacity="0" />
              </linearGradient>
            </defs>
            <g clipPath="url(#logo-clip)">
              {/* Wide rect sweeps horizontally carrying the rotated gradient */}
              <motion.rect
                width="3000"
                height="3000"
                x="-1000"
                y="-1000"
                fill="url(#sweep-gradient)"
                initial={{ translateX: -2000 }}
                animate={{ translateX: isSolidifying ? 2000 : -2000 }}
                transition={{ 
                  duration: sceneKey === 'solidify' ? 1.2 : 0, 
                  ease: "easeInOut", 
                  delay: sceneKey === 'solidify' ? 0.1 : 0 
                }}
              />
            </g>
          </svg>
        </motion.div>

      </motion.div>
    </div>
  );
}
